def units(s):
 u={'title':s['titleJa']}
 shared=len(set(c.get('learningActivity',{}).get('ja') for c in s['clusters']))<=1
 def add(k,v):
  if v:u[k]=v
 for c in s['clusters']:
  add(c['id']+':title',c['titleJa'])
  for p in c['paragraphs']:add(p['id'],p['ja'])
  for k,suf in [('applicationPromptJa','prompt'),('reflectionJa','reflection')]:add(c['id']+':'+suf,c.get(k))
  add(c['id']+':caption',c.get('illustration',{}).get('captionJa'))
  add('learningActivity' if shared else c['id']+':activity',c.get('learningActivity',{}).get('ja'))
  for t in c.get('terms',[]):add(c['id']+':term:'+t['ja'],t['ja'])
 for t in s.get('keyTerms',[]):add('keyTerm:'+t['term'],t['term'])
 for i,a in enumerate(s.get('illustrations',[])):add(f'illustration:{i}:alt',a['altJa'])
 return u
out={'locales':['hi','ne'],'sessions':[]}
for n,raw in data.items():
 s=json.loads((ROOT/f'docs/ssw-workspace/kensetsu/shared-session-{n}.json').read_text())
 u=units(s); rows=[line.split('|||') for line in raw.splitlines()]
 assert len(rows)==len(u),(n,len(rows),len(u))
 assert all(len(r)==2 and all(t.strip() for t in r) for r in rows)
 out['sessions'].append({'sessionId':s['id'],'entries':{k:{'sourceJa':ja,'translations':dict(zip(['hi','ne'],tr))} for (k,ja),tr in zip(u.items(),rows)}})
Path(__file__).with_name('pair-hi-ne.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
print('Wrote',len(out['sessions']),'sessions',sum(len(s['entries']) for s in out['sessions']),'units')
